def _slew(cur, target, up, down, dt):
    """Moves a speed one step toward its target with separate acceleration and deceleration limits.

    The change is limited to up*dt when speeding up (|target| > |cur| and the same sign, or cur is 0) and to down*dt otherwise
    (slowing down or reversing).

    Args:
        cur (float): The current speed.
        target (float): The speed to approach.
        up (float): The largest rate of increase of the speed's magnitude, in speed units per second.
        down (float): The largest rate of decrease of the speed's magnitude (also used when reversing), in speed units per second.
        dt (float): The time step in seconds.

    Returns:
        float: The new speed, at most up*dt or down*dt away from `cur` and never beyond `target`.
    """
    speeding = abs(target) > abs(cur) and (cur == 0 or target * cur > 0)
    lim = (up if speeding else down) * dt
    return cur + max(-lim, min(lim, target - cur))


RESTORE_ON_RESUME = True      # tests set these False for the control runs
COMPENSATE_PAUSES = True


def _start_from_applied(S, obs):
    """Snap-back safety for the base: starts a controller from the Twist the loop applied last tick.

    The controllers slew from the Twist (linear speed in metres per second, yaw rate in radians per second) that the loop APPLIED
    last tick, not from their own memory of it. Normally they are the same numbers; after an operator has had control (the base was
    brought to rest, the controller was paused) the memory is stale and would make the first command a step to the old speed.
    Overwrites S["twist"].

    Args:
        S (dict): A controller's state dict; its "twist" entry is replaced.
        obs (dict): The observation; obs["applied"]["twist"] is the (linear, angular) Twist the loop applied.
    """
    S["twist"] = tuple(float(v) for v in obs["applied"]["twist"])


def _pose_controller(cfg, goal, max_lin, max_ang, tol_pos, tol_yaw, real_pos_tol, real_yaw_tol, max_reapproach):
    """Makes a go-to-pose controller: turn in place toward the goal, drive straight along the line to it, turn to the goal yaw.

    The legs are "TURN1" (turn toward the goal), "DRIVE" (straight line with cross-track correction), "TURN2" (turn to the goal yaw)
    and "SETTLE" (wait at rest; start again if the base drifted out of the aim). The pose must be within tol_pos / tol_yaw (the aim)
    with the base at rest for drive_settle_s; after max_reapproach corrective re-approaches a pose that is not within the aim but is
    within real_pos_tol / real_yaw_tol still counts as arrived; one that is not within those is a failure.

    Args:
        cfg (dict): The staging configuration (STAGING_CFG); uses drive_ang_decel, drive_creep_ang, drive_turn_first_tol,
            drive_lin_decel, drive_creep_lin, drive_cross_track_gain, drive_steer_max, drive_steer_gain, drive_settle_s,
            drive_lin_accel and drive_ang_accel.
        goal (tuple): The goal pose (x, y, yaw) of the base in the world frame, in metres, metres and radians.
        max_lin (float): The largest forward speed, in metres per second.
        max_ang (float): The largest yaw rate, in radians per second.
        tol_pos (float): The aimed position tolerance, in metres.
        tol_yaw (float): The aimed yaw tolerance, in radians.
        real_pos_tol (float): The position tolerance that still counts as arrived after the re-approaches ran out, in metres.
        real_yaw_tol (float): The yaw tolerance that still counts as arrived after the re-approaches ran out, in radians.
        max_reapproach (int): The number of corrective re-approaches allowed before the controller accepts or fails.

    Returns:
        dict: "reset" (callable): reset(x, y, yaw) starts a new approach from the given base pose (metres, metres, radians).
            "step" (callable): step(obs, t, dt) -> (commands, status). `commands` is a list holding one base command
                {"mode": "base", "twist": (linear metres per second, angular radians per second)}, or [] when the status is "failed"; `status` is "running",
                "arrived" or "failed" (S["fail"] says why).
            "S" (dict): The controller state: "leg" (str, "TURN1", "DRIVE", "TURN2" or "SETTLE"), "twist" (the last Twist), "ok_since"
                (time the pose first held within the aim at rest, or None), "reapproach" (int, re-approaches so far), "line"
                ((x, y, heading) where the straight leg started, or None), "first_turn" (degrees turned toward the goal at the
                start, or None), "final_turn" (degrees of the in-place turn at the goal, or None), "fail" (message or None) and
                "aim_missed" (bool, True if it arrived within the real tolerance but not the aim).
    """
    gx, gy, gyaw = goal
    S = {"leg": "TURN1", "twist": (0.0, 0.0), "ok_since": None, "reapproach": 0, "line": None, "first_turn": None, "final_turn": None,
         "fail": None, "aim_missed": False}

    def reset(x, y, yaw):
        """Starts a new approach: clears the state and picks the first leg.

        The first leg is "TURN1" if the base is at least tol_pos from the goal, else "TURN2". Changes S in the enclosing scope.

        Args:
            x (float): The base x position in the world frame, in metres.
            y (float): The base y position in the world frame, in metres.
            yaw (float): The base yaw in radians. Not used.
        """
        S.update(leg="TURN1" if math.hypot(gx - x, gy - y) >= tol_pos else "TURN2", twist=(0.0, 0.0), ok_since=None, reapproach=0,
                 line=None, first_turn=None, final_turn=None, fail=None, aim_missed=False)

    def turn_rate(err, tol_leg):
        """Gives the yaw rate for turning in place toward a heading error, slowing down as the error shrinks.

        The size is sqrt(2 * drive_ang_decel * (|err| - 0.3 * tol_leg)), at most max_ang and at least min(drive_creep_ang, max_ang).

        Args:
            err (float): The heading error to remove, in radians; its sign gives the turn direction.
            tol_leg (float): The tolerance of this turn, in radians.

        Returns:
            float: The commanded yaw rate in radians per second, with the sign of `err`.
        """
        w = math.sqrt(2 * cfg["drive_ang_decel"] * max(abs(err) - 0.3 * tol_leg, 0.0))
        return math.copysign(max(min(w, max_ang), min(cfg["drive_creep_ang"], max_ang)), err)

    def step(obs, t, dt):
        """Runs one control tick of the go-to-pose controller.

        Reads obs["base_pose"] and obs["applied"]["twist"]; changes S in the enclosing scope (leg, twist, the settle clock, the
        re-approach count, the recorded turns, the failure message). It moves from "TURN1" to "DRIVE" when the heading error is below
        drive_turn_first_tol; the straight leg steers at the line from its start to the goal (cross-track gain, steering limit), turns
        again if the heading is more than 20 degrees off the line while farther than 0.3 m, and stops when within tol_pos or past the
        goal; "TURN2" turns to the goal yaw; "SETTLE" waits at rest for drive_settle_s, re-approaching if the base drifted out of the aim.

        Args:
            obs (dict): The observation; uses "base_pose" ((x, y, yaw), metres and radians) and "applied" ("twist").
            t (float): The simulation time in seconds.
            dt (float): The control tick length in seconds.

        Returns:
            tuple: (commands, status). `commands` is a list with one {"mode": "base", "twist": (linear, angular)} command, or an
            empty list when the status is "failed". `status` is "running", "arrived" or "failed".
        """
        _start_from_applied(S, obs)
        x, y, yaw = obs["base_pose"]
        dist = math.hypot(gx - x, gy - y)
        bearing = math.atan2(gy - y, gx - x)
        leg = S["leg"]
        lin_t = ang_t = 0.0
        if leg == "TURN1":
            if dist < tol_pos:
                leg = "TURN2"
            else:
                err = wrap(bearing - yaw)
                if S["first_turn"] is None:
                    S["first_turn"] = math.degrees(err)
                if abs(err) < cfg["drive_turn_first_tol"]:
                    leg = "DRIVE"
                    S["line"] = (x, y, bearing)                  # the straight leg follows this line to the goal
                else:
                    ang_t = turn_rate(err, cfg["drive_turn_first_tol"])
        if leg == "DRIVE":
            sx, sy, lh = S["line"]
            ux, uy = math.cos(lh), math.sin(lh)
            along_rem = (gx - x) * ux + (gy - y) * uy            # distance left along the line
            lateral = -(x - sx) * uy + (y - sy) * ux             # left of the line is positive
            if dist < tol_pos:
                leg = "TURN2"
            elif along_rem < 0.0:                                # went past the goal without arriving: stop, SETTLE will re-approach
                leg = "TURN2"
            else:
                v = math.sqrt(2 * cfg["drive_lin_decel"] * max(dist - 0.3 * tol_pos, 0.0))
                lin_t = max(min(v, max_lin), min(cfg["drive_creep_lin"], max_lin))
                # heading plus cross-track correction (Stanley): aim at the line, a little further along it the further off it we are
                want = lh - math.atan2(cfg["drive_cross_track_gain"] * lateral, max(S["twist"][0], 0.1))
                err = wrap(want - yaw)
                ang_t = max(-cfg["drive_steer_max"], min(cfg["drive_steer_max"], cfg["drive_steer_gain"] * err))
                if abs(wrap(lh - yaw)) > math.radians(20) and dist > 0.3:     # knocked far off course: turn again
                    leg = "TURN1"
                    lin_t = ang_t = 0.0
        if leg == "TURN2":
            err = wrap(gyaw - yaw)
            if S["final_turn"] is None:
                S["final_turn"] = math.degrees(err)              # the in-place turn at the goal
            if abs(err) < tol_yaw:
                leg = "SETTLE"
            else:
                ang_t = turn_rate(err, tol_yaw)
        if leg == "SETTLE":
            lin, ang = S["twist"]
            yaw_err = abs(wrap(gyaw - yaw))
            at_rest = abs(lin) < 1e-9 and abs(ang) < 1e-9
            in_tol = dist < tol_pos and yaw_err < tol_yaw
            if not in_tol and at_rest:                           # drifted out after stopping: re-approach, or give up
                S["reapproach"] += 1
                S["ok_since"] = None
                if S["reapproach"] > max_reapproach:
                    if dist < real_pos_tol and yaw_err < real_yaw_tol:
                        S["aim_missed"] = True                   # not within the tighter aim, but within the tolerance: accepted
                        S["leg"] = leg
                        return [{"mode": "base", "twist": (0.0, 0.0)}], "arrived"
                    S["fail"] = (f"the base is not within {real_pos_tol * 100:.0f} cm / {math.degrees(real_yaw_tol):.0f} deg of the staging "
                                 f"pose after {max_reapproach} corrective re-approaches (now {dist * 1000:.1f} mm, {math.degrees(yaw_err):.2f} deg)")
                    return [], "failed"
                S["final_turn"] = None
                leg = "TURN1" if dist >= tol_pos else "TURN2"
            elif in_tol and at_rest:
                if S["ok_since"] is None:
                    S["ok_since"] = t
                if t - S["ok_since"] >= cfg["drive_settle_s"]:
                    S["leg"] = leg
                    return [{"mode": "base", "twist": (0.0, 0.0)}], "arrived"
        S["leg"] = leg
        lin, ang = S["twist"]
        lin = _slew(lin, lin_t, cfg["drive_lin_accel"], cfg["drive_lin_decel"], dt)
        ang = _slew(ang, ang_t, cfg["drive_ang_accel"], cfg["drive_ang_decel"], dt)
        S["twist"] = (lin, ang)
        return [{"mode": "base", "twist": (lin, ang)}], "running"

    return {"reset": reset, "step": step, "S": S}


def _creep_controller(cfg, goal, tol_pos, tol_yaw, real_pos_tol, real_yaw_tol, max_pos, max_yaw):
    """Makes the base-pose correction controller for an extended arm.

    It does a creep-speed yaw turn in place, then a creep-speed straight move along the heading (forward or back). There is no turn
    toward a bearing: a sideways error is not corrected (a differential base would have to turn about 90 degrees with the arm out), so
    it makes the controller fail. The stages are "CHECK" (fail if the correction is too large or sideways), "YAW", "MOVE" and "SETTLE".

    Args:
        cfg (dict): The staging configuration (STAGING_CFG); uses drive_creep_ang, drive_creep_lin, drive_settle_s, drive_lin_accel,
            drive_lin_decel, drive_ang_accel and drive_ang_decel.
        goal (tuple): The goal pose (x, y, yaw) of the base in the world frame, in metres, metres and radians.
        tol_pos (float): The aimed along-heading position tolerance, in metres.
        tol_yaw (float): The aimed yaw tolerance, in radians.
        real_pos_tol (float): The position tolerance at the end and for the sideways error, in metres.
        real_yaw_tol (float): The yaw tolerance at the end, in radians.
        max_pos (float): The largest along-heading error that may be corrected, in metres.
        max_yaw (float): The largest yaw error that may be corrected, in radians.

    Returns:
        dict: "step" (callable): step(obs, t, dt) -> (commands, status), the same two-item result as the step of _pose_controller
            ("running", "arrived" or "failed").
            "S" (dict): The controller state: "stage" (str), "twist" (the last Twist), "ok_since" (time the pose first held at rest,
                or None) and "fail" (message or None; says why it failed).
    """
    gx, gy, gyaw = goal
    S = {"stage": "CHECK", "twist": (0.0, 0.0), "ok_since": None, "fail": None}

    def errors(obs):
        """Gives the base pose error to the goal in the base's own frame.

        Args:
            obs (dict): The observation; uses obs["base_pose"] ((x, y, yaw), metres and radians).

        Returns:
            tuple: (along, lateral, yaw_err) in metres, metres and radians. along is positive when the goal is ahead of the base,
            lateral is positive when the goal is to the base's left, and yaw_err is the goal yaw minus the base yaw wrapped to
            (-pi, pi].
        """
        x, y, yaw = obs["base_pose"]
        ex, ey = gx - x, gy - y
        return ex * math.cos(yaw) + ey * math.sin(yaw), -ex * math.sin(yaw) + ey * math.cos(yaw), wrap(gyaw - yaw)   # along, lateral (left +), yaw

    def step(obs, t, dt):
        """Runs one control tick of the creep-speed correction.

        Reads obs["base_pose"] and obs["applied"]["twist"]; changes S in the enclosing scope. In "CHECK" it fails if the along error is
        above max_pos, the yaw error above max_yaw or the sideways error above real_pos_tol; "YAW" turns at the creep rate until the
        yaw error is below tol_yaw; "MOVE" drives at the creep speed until the along error is below tol_pos; "SETTLE" waits at rest
        for drive_settle_s and fails if the final error is outside real_pos_tol / real_yaw_tol.

        Args:
            obs (dict): The observation; uses "base_pose" ((x, y, yaw), metres and radians) and "applied" ("twist").
            t (float): The simulation time in seconds.
            dt (float): The control tick length in seconds.

        Returns:
            tuple: (commands, status). `commands` is a list with one {"mode": "base", "twist": (linear, angular)} command, or an
            empty list when the status is "failed". `status` is "running", "arrived" or "failed".
        """
        _start_from_applied(S, obs)
        along, lateral, yaw_err = errors(obs)
        if S["stage"] == "CHECK":
            if abs(along) > max_pos or abs(yaw_err) > max_yaw or abs(lateral) > real_pos_tol:
                S["fail"] = (f"the correction with the arm extended would be too large or sideways (along {along * 1000:+.1f} mm, sideways {lateral * 1000:+.1f} mm, "
                             f"yaw {math.degrees(yaw_err):+.2f} deg; allowed along {max_pos * 1000:.0f} mm, sideways {real_pos_tol * 1000:.0f} mm, yaw {math.degrees(max_yaw):.1f} deg)")
                return [], "failed"
            S["stage"] = "YAW"
        lin_t = ang_t = 0.0
        if S["stage"] == "YAW":
            if abs(yaw_err) < tol_yaw:
                S["stage"] = "MOVE"
            else:
                ang_t = math.copysign(cfg["drive_creep_ang"], yaw_err)
        if S["stage"] == "MOVE":
            if abs(along) < tol_pos:
                S["stage"] = "SETTLE"
            else:
                lin_t = math.copysign(cfg["drive_creep_lin"], along)
        if S["stage"] == "SETTLE":
            lin, ang = S["twist"]
            if abs(lin) < 1e-9 and abs(ang) < 1e-9:
                pos_err = math.hypot(gx - obs["base_pose"][0], gy - obs["base_pose"][1])
                if pos_err < real_pos_tol and abs(yaw_err) < real_yaw_tol:
                    if S["ok_since"] is None:
                        S["ok_since"] = t
                    if t - S["ok_since"] >= cfg["drive_settle_s"]:
                        return [{"mode": "base", "twist": (0.0, 0.0)}], "arrived"
                else:
                    S["fail"] = f"after the creep correction the base is still {pos_err * 1000:.1f} mm / {math.degrees(abs(yaw_err)):.2f} deg off"
                    return [], "failed"
        lin, ang = S["twist"]
        lin = _slew(lin, lin_t, cfg["drive_lin_accel"], cfg["drive_lin_decel"], dt)
        ang = _slew(ang, ang_t, cfg["drive_ang_accel"], cfg["drive_ang_decel"], dt)
        S["twist"] = (lin, ang)
        return [{"mode": "base", "twist": (lin, ang)}], "running"

    return {"step": step, "S": S}


def make_staging_source(model, data, task_cfg=TASK_CFG, cfg=STAGING_CFG, points_fn=framing_points):
    """Makes the staging source: it drives the robot from the spawn state to the HANDOFF state, phase by phase.

    The phases are DRIVE, PEDESTAL, CORRECT_PEDESTAL, ARMS, CORRECT_ARMS, NECK and DONE (see the module docstring). The source keeps
    its internal bookkeeping in three dicts of the enclosing scope: `state` (public, below), `P` (phase machinery: "entered", "still_since"
    (time the settle condition first held), "neck_sent", "neck_resent", "neck_targets", "u" (ARMS time fraction), "path" (ARMS joint-space
    waypoints), "last_arm" (the last arm targets sent), "corr" (the record of the running correction), "lim_grip" (rate-limit the gripper
    after a hand-back), "paused" (seconds an operator had control), "last_t" (time of the previous step), "restore" (a restore after a
    hand-back is pending)) and `M` (measurements for observe() and report()).

    Args:
        model (mujoco.MjModel): The compiled model.
        data (mujoco.MjData): The simulation data; read for clearances and for the neck framing.
        task_cfg (dict): The task configuration (src/task_config.py); uses "arm", "staging_xy" and "staging_yaw" (the goal base pose,
            metres and radians), "spawn_xy" (metres), "pedestal_q" (metres), "ready_q" and "ready_via_q" (joint angles in radians).
            Defaults to TASK_CFG.
        cfg (dict): The staging configuration (STAGING_CFG): the speeds, ramps, tolerances, settle values and timeouts of the phases.
            Defaults to STAGING_CFG.
        points_fn (callable): points_fn(model, data, task_cfg) -> {name: world-frame (x, y, z) point in metres}, the points the neck
            camera must keep in view. Defaults to framing_points (src/task_beaker_hotplate.py).

    Returns:
        dict: The source, with the keys:
            "name" (str): "staging".
            "step" (callable): step(obs) -> list of commands, for one control tick. Returns [] once the stage is done or has an
                error. A command is {"mode": "base", "twist": (linear metres per second, angular radians per second)}, {"mode": "pedestal", "height": metres},
                {"mode": "arms", "arm_targets": {arm: 7 joint angles in radians}, "gripper": {arm: finger opening in metres}} or
                {"mode": "neck", "neck_targets": {joint name: radians}}.
            "state" (dict): The public state: "phase" (str), "done" (bool), "error" (str or None; a failure message, which the runner
                turns into STAGING_FAILED), "phases" ({name: {"start", "end", "p0", "paused_s"}}: start and end simulation times in
                seconds, p0 the operator time before the phase and paused_s the operator time within it), "arrival" (None, or
                {"pos_err" (metres), "yaw_err_deg", "ok" (bool)} at the end of DRIVE), "first_turn_deg" and "final_turn_deg" (degrees
                turned at the start and end of DRIVE), "planned_final_turn_deg" (the final turn the straight line from the spawn
                implies), "reapproaches" (int), "framing_report" (the neck framing report of src/neck_framing.frame_points(), or
                None) and "corrections" (list of records {"phase", "needed" (bool), "before", "after" (pose error dicts, see pose_err),
                "duration_s", "status" (str), "next" (the phase that follows), "min_base_clearance_mm", "min_arm_clearance_mm"}).
            "observe" (callable): observe(obs) -> None; records the base drift per phase and the clearance during DRIVE.
            "report" (callable): report() -> dict, the staging part of the episode summary.
            "resume" (callable): resume() -> None; called when an operator hands control back.
            "restore_step" (callable): restore_step(obs, t, dt) -> (commands, finished); see restore_step() below.
            "restoring" (callable): restoring() -> bool; True while a restore after a hand-back is pending.
    """
    arm = task_cfg["arm"]
    arm_idx = arm_ids(model, arm)
    ped_vadr = int(model.joint(robot_specs.PEDESTAL_SPECS["joints"][0]).dofadr[0])
    neck = neck_ids(model, robot_specs.NECK_SPECS)
    gx, gy = task_cfg["staging_xy"]
    gyaw = task_cfg["staging_yaw"]
    goal = (gx, gy, gyaw)
    spawn = task_cfg["spawn_xy"]
    planned_heading = math.atan2(gy - spawn[1], gx - spawn[0])
    state = {"phase": "DRIVE", "done": False, "error": None, "phases": {}, "arrival": None, "final_turn_deg": None,
             "planned_final_turn_deg": math.degrees(wrap(gyaw - planned_heading)), "first_turn_deg": None, "reapproaches": 0,
             "framing_report": None, "corrections": []}
    P = {"entered": False, "still_since": None, "neck_sent": False, "u": 0.0, "last_arm": None, "path": None, "neck_targets": None,
         "corr": None, "lim_grip": False, "paused": 0.0, "last_t": None, "restore": False, "neck_resent": False}
    pos_tol, yaw_tol = cfg["drive_pos_tol"], cfg["drive_yaw_tol"]
    frac = cfg["correction_aim_frac"]
    drive_ctl = _pose_controller(cfg, goal, cfg["drive_max_lin_vel"], cfg["drive_max_ang_vel"], pos_tol, yaw_tol, pos_tol, yaw_tol,
                                 cfg["drive_max_reapproach"])
    ped_ctl = _pose_controller(cfg, goal, cfg["drive_max_lin_vel"], cfg["drive_max_ang_vel"], frac * pos_tol, frac * yaw_tol, pos_tol, yaw_tol,
                               cfg["drive_max_reapproach"])
    arm_ctl = _creep_controller(cfg, goal, frac * pos_tol, frac * yaw_tol, pos_tol, yaw_tol, cfg["correction_arms_max_pos"], cfg["correction_arms_max_yaw"])
    drive_ctl["started"] = ped_ctl["started"] = False

    # clearances to the bench, watched every tick during the extended-arm correction
    base_names = ["base_link", "right_link", "left_Link", "right_front_link", "right_rear_link", "left_front_link", "left_rear_link"]
    base_geoms = [g for g in range(model.ngeom) if model.body(int(model.geom_bodyid[g])).name in base_names]
    arm_geoms = [g for g in range(model.ngeom) if model.geom_group[g] == 3 and model.body(int(model.geom_bodyid[g])).name.startswith(f"openarm_{arm}_")
                 and not model.body(int(model.geom_bodyid[g])).name.endswith("link0")]
    bench_geoms = [g for g in range(model.ngeom) if int(model.geom_bodyid[g]) == model.body("bench").id]
    ft = np.zeros(6)

    def clearances():
        """Measures how close the base and the task arm are to the bench.

        Returns:
            tuple: (base, arm) smallest distances in metres between the base geoms and the bench geoms, and between the task arm's
            geoms (collision group 3, without link0) and the bench geoms. A negative value means penetration. Distances are looked up
            to 1.0 m.
        """
        d = lambda A: min(mujoco.mj_geomDistance(model, data, a, b, 1.0, ft) for a in A for b in bench_geoms)
        return d(base_geoms), d(arm_geoms)

    def close_phase(t):
        """Ends the current phase's record: stores its end time and the operator time inside it.

        Does nothing if the phase has no record. Changes state["phases"][phase] ("end", "paused_s") in the enclosing scope.

        Args:
            t (float): The simulation time in seconds.
        """
        rec = state["phases"].get(state["phase"])
        if rec is not None:
            rec["end"], rec["paused_s"] = t, P["paused"] - rec["p0"]

    def elapsed(t):
        """Gives the time spent in the current phase, not counting the time an operator had control.

        The operator time is left out so that a phase does not time out because of it.

        Args:
            t (float): The simulation time in seconds.

        Returns:
            float: Seconds in the current phase.
        """
        rec = state["phases"][state["phase"]]
        return t - rec["start"] - (P["paused"] - rec["p0"])

    def enter(name, t):
        """Ends the current phase and starts another.

        Closes the current phase, sets state["phase"], opens its record in state["phases"] and clears P["still_since"].

        Args:
            name (str): The phase to enter.
            t (float): The simulation time in seconds.
        """
        close_phase(t)
        state["phase"] = name
        state["phases"][name] = {"start": t, "end": None, "p0": P["paused"]}
        P.update(still_since=None)

    def still_for(t, ok, dwell):
        """Tells whether a condition has held for a given time.

        Uses and changes P["still_since"] in the enclosing scope: it is cleared when `ok` is false and set to `t` when `ok` first
        becomes true.

        Args:
            t (float): The simulation time in seconds.
            ok (bool): Whether the condition holds now.
            dwell (float): How long it must have held, in seconds.

        Returns:
            bool: True once `ok` has held for `dwell` seconds.
        """
        if not ok:
            P["still_since"] = None
            return False
        if P["still_since"] is None:
            P["still_since"] = t
        return t - P["still_since"] >= dwell

    def fail(t, msg):
        """Records a staging failure and ends the current phase's record.

        Args:
            t (float): The simulation time in seconds.
            msg (str): The failure message, stored in state["error"].
        """
        state["error"] = msg
        close_phase(t)

    def pose_err(obs):
        """Gives the base pose error to the staging pose, in the staging pose's frame.

        Args:
            obs (dict): The observation; uses obs["base_pose"] ((x, y, yaw), metres and radians).

        Returns:
            dict: "pos_mm" (distance to the staging position, millimetres), "yaw_deg" (base yaw minus staging yaw, wrapped, degrees),
            "along_mm" (positive when the base is short of the staging pose, i.e. farther from the bench) and "lateral_mm" (positive
            when the staging pose is to the base's left); both in millimetres along and across the staging heading.
        """
        x, y, yaw = obs["base_pose"]
        ex, ey = gx - x, gy - y
        # along > 0: the base is short of the staging pose (farther from the bench); lateral > 0: the staging pose is to the base's left
        return {"pos_mm": 1000 * math.hypot(ex, ey), "yaw_deg": math.degrees(wrap(yaw - gyaw)),
                "along_mm": 1000 * (ex * math.cos(gyaw) + ey * math.sin(gyaw)), "lateral_mm": 1000 * (-ex * math.sin(gyaw) + ey * math.cos(gyaw))}

    # ------------------------------------------------------------------ DRIVE
    def drive(obs, t, dt):
        """Runs the DRIVE phase: go to the staging pose with the go-to-pose controller.

        Resets the controller on the first call, copies its turn and re-approach records into `state`, and on arrival stores
        state["arrival"] and enters PEDESTAL; on failure stores state["arrival"] (with "ok" False) and sets state["error"].

        Args:
            obs (dict): The observation; uses "base_pose" and "applied".
            t (float): The simulation time in seconds.
            dt (float): The control tick length in seconds.

        Returns:
            list: The base command from the controller (empty when it failed).
        """
        if not drive_ctl["started"]:
            drive_ctl["started"] = True
            drive_ctl["reset"](*obs["base_pose"])
        cmds, status = drive_ctl["step"](obs, t, dt)
        S = drive_ctl["S"]
        state["first_turn_deg"], state["final_turn_deg"], state["reapproaches"] = S["first_turn"], S["final_turn"], S["reapproach"]
        if status == "failed":
            state["arrival"] = {"pos_err": math.hypot(gx - obs["base_pose"][0], gy - obs["base_pose"][1]),
                                "yaw_err_deg": abs(math.degrees(wrap(gyaw - obs["base_pose"][2]))), "ok": False}
            fail(t, "DRIVE: " + S["fail"])
        elif status == "arrived":
            e = pose_err(obs)
            state["arrival"] = {"pos_err": e["pos_mm"] / 1000, "yaw_err_deg": abs(e["yaw_deg"]), "ok": True}
            enter("PEDESTAL", t)
        return cmds

    # ------------------------------------------------------------------ PEDESTAL
    def pedestal(obs, t, dt):
        """Runs the PEDESTAL phase: ramp the pedestal command to task_cfg["pedestal_q"] and wait until it has settled.

        The command moves at most pedestal_speed * dt per tick from the applied height. When the pedestal is within pedestal_tol of the
        target, the applied command is at the target and the pedestal joint speed has been below pedestal_settle_vel for pedestal_settle_s,
        it starts the CORRECT_PEDESTAL check (begin_correction) and then goes on to ARMS.

        Args:
            obs (dict): The observation; uses "pedestal_height" and "applied" ("pedestal"), both in metres, and "joint_velocities".
            t (float): The simulation time in seconds.
            dt (float): The control tick length in seconds.

        Returns:
            list: [{"mode": "pedestal", "height": metres}], or [] when the command is at the target or a correction check was begun.
        """
        target = task_cfg["pedestal_q"]
        applied = obs["applied"]["pedestal"]
        if abs(obs["pedestal_height"] - target) < cfg["pedestal_tol"] and abs(applied - target) < 1e-9 and \
                still_for(t, abs(obs["joint_velocities"][ped_vadr]) < cfg["pedestal_settle_vel"], cfg["pedestal_settle_s"]):
            return begin_correction(obs, t, "CORRECT_PEDESTAL", "ARMS")
        if abs(applied - target) < 1e-9:
            return []
        step = cfg["pedestal_speed"] * dt
        return [{"mode": "pedestal", "height": applied + max(-step, min(step, target - applied))}]

    # ------------------------------------------------------------------ corrections
    def begin_correction(obs, t, name, nxt):
        """Checks the base pose; enters the correction phase if it is outside the tolerance, else goes on.

        Appends a correction record to state["corrections"] (status "not needed" or "running"). The pose is outside the tolerance when
        its position error exceeds drive_pos_tol or its yaw error exceeds drive_yaw_tol. For "CORRECT_PEDESTAL" it also resets the
        pedestal-correction controller. Sets P["corr"] to the record and enters `name` if a correction is needed, else enters `nxt`.

        Args:
            obs (dict): The observation; uses "base_pose".
            t (float): The simulation time in seconds.
            name (str): The correction phase to enter, "CORRECT_PEDESTAL" or "CORRECT_ARMS".
            nxt (str): The phase to enter if no correction is needed, and after the correction.

        Returns:
            list: Always empty (no command this tick).
        """
        e = pose_err(obs)
        needed = e["pos_mm"] / 1000 > pos_tol or abs(e["yaw_deg"]) > math.degrees(yaw_tol)
        rec = {"phase": name, "needed": needed, "before": e, "after": e, "duration_s": 0.0, "status": "not needed", "next": nxt,
               "min_base_clearance_mm": None, "min_arm_clearance_mm": None}
        state["corrections"].append(rec)
        if not needed:
            enter(nxt, t)
            return []
        rec["status"] = "running"
        if name == "CORRECT_PEDESTAL":
            ped_ctl["reset"](*obs["base_pose"])
        P["corr"] = rec
        enter(name, t)
        return []

    def correct_pedestal(obs, t, dt):
        """Runs the CORRECT_PEDESTAL phase: move the base back to the staging pose with the go-to-pose controller.

        Args:
            obs (dict): The observation; uses "base_pose" and "applied".
            t (float): The simulation time in seconds.
            dt (float): The control tick length in seconds.

        Returns:
            list: The base command from finish_correction().
        """
        cmds, status = ped_ctl["step"](obs, t, dt)
        return finish_correction(obs, t, status, cmds, ped_ctl["S"]["fail"], ped_ctl["S"])

    def correct_arms(obs, t, dt):
        """Runs the CORRECT_ARMS phase: correct the base pose at creep speed with the arm extended, watching the clearances.

        Every tick it measures the base-to-bench and arm-to-bench clearances, keeps their minimum in the correction record, and fails
        (record status "failed (clearance)", state["error"] set) if either is below correction_arms_min_base_clearance or
        correction_arms_min_arm_clearance. Otherwise it steps the creep controller.

        Args:
            obs (dict): The observation; uses "base_pose" and "applied".
            t (float): The simulation time in seconds.
            dt (float): The control tick length in seconds.

        Returns:
            list: The base command from finish_correction(), or [] after a clearance failure.
        """
        rec = P["corr"]
        bc, ac = clearances()                                     # every tick: the extended arm must stay clear of the bench
        rec["min_base_clearance_mm"] = 1000 * bc if rec["min_base_clearance_mm"] is None else min(rec["min_base_clearance_mm"], 1000 * bc)
        rec["min_arm_clearance_mm"] = 1000 * ac if rec["min_arm_clearance_mm"] is None else min(rec["min_arm_clearance_mm"], 1000 * ac)
        if bc < cfg["correction_arms_min_base_clearance"] or ac < cfg["correction_arms_min_arm_clearance"]:
            rec["status"] = "failed (clearance)"
            fail(t, f"CORRECT_ARMS: clearance to the bench too small (base {bc * 1000:.1f} mm, arm {ac * 1000:.1f} mm; minimums "
                    f"{cfg['correction_arms_min_base_clearance'] * 1000:.0f} / {cfg['correction_arms_min_arm_clearance'] * 1000:.0f} mm)")
            return []
        cmds, status = arm_ctl["step"](obs, t, dt)
        return finish_correction(obs, t, status, cmds, arm_ctl["S"]["fail"], arm_ctl["S"])

    def finish_correction(obs, t, status, cmds, why, S):
        """Updates the running correction record from a controller's result and moves on when it is over.

        Sets rec["duration_s"] each tick. On "failed" it sets the record status to "failed", stores the pose error after, and fails with
        the phase name and `why`. On "arrived" it stores the pose error after, sets the status to "done" (with a note if the aim was
        missed but the tolerance met) and enters the record's "next" phase.

        Args:
            obs (dict): The observation; uses "base_pose".
            t (float): The simulation time in seconds.
            status (str): The controller's status: "running", "arrived" or "failed".
            cmds (list): The controller's commands for this tick.
            why (str or None): The controller's failure message.
            S (dict): The controller's state dict (its "aim_missed" entry, if any, is read).

        Returns:
            list: `cmds`, or [] if the controller failed.
        """
        rec = P["corr"]
        rec["duration_s"] = elapsed(t)
        if status == "failed":
            rec["status"] = "failed"
            rec["after"] = pose_err(obs)
            fail(t, f"{state['phase']}: {why}")
            return []
        if status == "arrived":
            rec["after"] = pose_err(obs)
            rec["status"] = "done" + (" (within the tolerance, not the aim)" if S.get("aim_missed") else "")
            enter(rec["next"], t)
        return cmds

    # ------------------------------------------------------------------ ARMS
    def arms(obs, t, dt):
        """Runs the ARMS phase: move the task arm along rest -> ready_via_q -> ready_q with minimum jerk, opening the gripper.

        On the first call it builds the joint-space path from the arm's applied targets through task_cfg["ready_via_q"] (if not None)
        to task_cfg["ready_q"], with arc-length fractions in P["path"]. The time fraction P["u"] advances by dt / arms_move_s per tick,
        but only if the last command was applied. The targets go through rate_limit() (arm_max_speed) from the applied targets, and
        after a hand-back (P["lim_grip"]) the gripper target is rate-limited (gripper_max_speed) until it is back on the path. When
        the time fraction has reached 1, every joint is within arms_tol of the ready pose and the joints have been slower than
        arms_settle_vel for arms_settle_s, it starts the CORRECT_ARMS check (begin_correction) and then goes on to NECK.

        Args:
            obs (dict): The observation; uses "applied" ("arm_targets", "gripper"), "joint_angles" and "joint_velocities".
            t (float): The simulation time in seconds.
            dt (float): The control tick length in seconds.

        Returns:
            list: [{"mode": "arms", "arm_targets": {arm: 7 joint angles in radians}, "gripper": {arm: finger opening in metres}}],
            or [] when a correction check was begun.
        """
        applied = np.array(obs["applied"]["arm_targets"][arm])
        ready = np.array(task_cfg["ready_q"], float)
        if P["path"] is None:
            via = task_cfg["ready_via_q"]
            pts = np.array([applied] + ([np.array(via, float)] if via is not None else []) + [ready])
            seg = np.linalg.norm(np.diff(pts, axis=0), axis=1)
            P["path"] = (pts, np.r_[0.0, np.cumsum(seg) / seg.sum()])
        q_now = np.array([obs["joint_angles"][a] for a in arm_idx["qadr"]])
        qd = max(abs(obs["joint_velocities"][v]) for v in arm_idx["vadr"])
        if P["u"] >= 1.0 and np.abs(q_now - ready).max() < cfg["arms_tol"] and \
                still_for(t, qd < cfg["arms_settle_vel"], cfg["arms_settle_s"]):
            return begin_correction(obs, t, "CORRECT_ARMS", "NECK")
        if P["last_arm"] is None or np.allclose(applied, P["last_arm"], atol=1e-12):      # advance only when the last command was applied
            P["u"] = min(1.0, P["u"] + dt / cfg["arms_move_s"])
        s = min_jerk(P["u"])
        pts, frac_ = P["path"]
        i = min(int(np.searchsorted(frac_, s, side="right")) - 1, len(pts) - 2)
        q = pts[i] + (s - frac_[i]) / (frac_[i + 1] - frac_[i]) * (pts[i + 1] - pts[i])
        # Snap-back safety: the targets start from the arm's CURRENT applied targets and move at most arm_max_speed. Normally the goal is within
        # reach and is returned exactly as before; after the operator has moved the arm (the policy was paused) the arm glides back to the path.
        q = rate_limit(applied, q, cfg["arm_max_speed"], dt)
        P["last_arm"] = q
        g = float(cfg["finger_open"] * s)
        if P["lim_grip"]:                  # after a hand-back: from the applied gripper target, at most gripper_max_speed, until it is back on the path
            g_lim = float(rate_limit([obs["applied"]["gripper"][arm]], [g], cfg["gripper_max_speed"], dt)[0])
            P["lim_grip"] = g_lim != g
            g = g_lim
        return [{"mode": "arms", "arm_targets": {arm: [float(v) for v in q]}, "gripper": {arm: g}}]

    # ------------------------------------------------------------------ NECK
    def neck_phase(obs, t, dt):
        """Runs the NECK phase: frame the task points with the neck camera, then hold until the neck has settled.

        On the first call it runs frame_points() on points_fn(model, data, task_cfg), stores the report in state["framing_report"] and
        the targets in P["neck_targets"], and commands them. Afterwards it waits until every neck joint is within neck_tol of its
        target and slower than neck_settle_vel for neck_settle_s, then enters DONE and sets state["done"].

        Args:
            obs (dict): The observation; uses "joint_angles" and "joint_velocities".
            t (float): The simulation time in seconds.
            dt (float): The control tick length in seconds. Not used.

        Returns:
            list: [{"mode": "neck", "neck_targets": {joint name: radians}}] on the first call, otherwise [].
        """
        if not P["neck_sent"]:
            targets, report = frame_points(model, data, points_fn(model, data, task_cfg))
            state["framing_report"] = report
            P["neck_targets"], P["neck_sent"] = targets, True
            return [{"mode": "neck", "neck_targets": targets}]
        q = np.array([obs["joint_angles"][a] for a in neck["qadr"]])
        goal_q = np.array([P["neck_targets"][n] for n in neck["names"]])
        qd = max(abs(obs["joint_velocities"][v]) for v in neck["vadr"])
        if np.abs(q - goal_q).max() < cfg["neck_tol"] and still_for(t, qd < cfg["neck_settle_vel"], cfg["neck_settle_s"]):
            enter("DONE", t)
            state["done"] = True
        return []

    phases = {"DRIVE": (drive, "drive_timeout"), "PEDESTAL": (pedestal, "pedestal_timeout"),
              "CORRECT_PEDESTAL": (correct_pedestal, "correction_timeout"), "ARMS": (arms, "arms_timeout"),
              "CORRECT_ARMS": (correct_arms, "correction_timeout"), "NECK": (neck_phase, "neck_timeout")}

    def step(obs):
        """Runs one control tick of the staging source.

        Does nothing once the stage is done or has failed. Otherwise: it detects that an operator had control (the source was not stepped
        for more than 1.5 ticks) and adds that time to P["paused"] (if COMPENSATE_PAUSES) and clears the settle clocks; runs the restore
        step first if a restore after a hand-back is pending; on the first call opens the DRIVE record and adds a command that holds the
        neck at its driving pose (NECK_SPECS["drive_pose"]); fails the stage if the phase timeout (cfg key per phase, operator time
        excluded) has passed; and runs the current phase function.

        Args:
            obs (dict): The loop's observation; uses "time" and "timestep" (seconds), "steps_per_frame" and whatever the phases read.

        Returns:
            list: The commands for this tick (see the "step" entry of the returned dict of make_staging_source()); empty if none.
        """
        if state["done"] or state["error"]:
            return []
        t = obs["time"]
        dt = obs["timestep"] * obs["steps_per_frame"]
        if P["last_t"] is not None and t - P["last_t"] > 1.5 * dt:          # not stepped for a while: an operator had control
            P["paused"] += (t - P["last_t"] - dt) if COMPENSATE_PAUSES else 0.0
            P["still_since"] = None
            for c in (drive_ctl, ped_ctl, arm_ctl):
                c["S"]["ok_since"] = None
        P["last_t"] = t
        if P["restore"]:
            cmds, finished = restore_step(obs, t, dt)
            if not finished:
                return cmds
        if not P["entered"]:
            P["entered"] = True
            state["phases"]["DRIVE"] = {"start": t, "end": None, "p0": 0.0}
            lead = [{"mode": "neck", "neck_targets": dict(zip(robot_specs.NECK_SPECS["active_joints"], robot_specs.NECK_SPECS["drive_pose"]))}] \
                if neck is not None else []                       # the neck looks ahead while driving (it already does; made explicit)
        else:
            lead = []
        phase = state["phase"]
        fn, timeout_key = phases[phase]
        if elapsed(t) > cfg[timeout_key]:
            fail(t, f"{phase} timed out after {cfg[timeout_key]:.0f} s")
            return []
        return lead + fn(obs, t, dt)

    # ------------------------------------------------------------------ measurements and report
    M = {"phase": None, "phase_base": {}, "drift": {}, "min_clearance": None, "handoff_base": None}

    def observe(obs):
        """Records the staging measurements for the report: base drift per phase and the clearance during DRIVE.

        Drift is the base's distance and yaw change from where the phase started, for every phase except DRIVE and the CORRECT phases
        (it also keeps the net value at the latest call). During DRIVE it keeps the smallest base-to-bench distance. The base pose
        when the stage became done is kept as the handoff pose. Changes M in the enclosing scope.

        Args:
            obs (dict): The observation; uses "base_pose" ((x, y, yaw), metres and radians).
        """
        x, y, yaw = obs["base_pose"]
        phase = "DONE" if state["done"] else state["phase"]
        if phase != M["phase"]:                                  # drift is measured against the pose the phase started from
            M["phase"] = phase
            M["phase_base"][phase] = (x, y, yaw)
            M["drift"].setdefault(phase, {"max_pos": 0.0, "max_yaw": 0.0})
        if state["done"] and M["handoff_base"] is None:
            M["handoff_base"] = (x, y, yaw)
        if phase != "DRIVE" and not phase.startswith("CORRECT"):
            x0, y0, yaw0 = M["phase_base"][phase]
            d = M["drift"][phase]
            d["max_pos"] = max(d["max_pos"], math.hypot(x - x0, y - y0))
            d["max_yaw"] = max(d["max_yaw"], abs(wrap(yaw - yaw0)))
            d["net_pos"], d["net_yaw"] = math.hypot(x - x0, y - y0), wrap(yaw - yaw0)
        elif phase == "DRIVE":
            c = min(mujoco.mj_geomDistance(model, data, a, b, 2.0, ft) for a in base_geoms for b in bench_geoms)
            M["min_clearance"] = c if M["min_clearance"] is None else min(M["min_clearance"], c)

    def report():
        """Builds the staging part of the episode summary.

        Returns:
            dict: "staging_error" (str or None), "phase_durations_s" ({phase: seconds without operator time, or None if the phase has
            not ended}, DONE left out), "phase_times" ({phase: [start, end]} simulation times in seconds), "arrival_at_end_of_drive"
            ({"pos_err_mm", "yaw_err_deg", "ok"} or None), "base_pose_error_at_handoff" ({"pos_err_mm", "yaw_err_deg", "along_mm",
            "lateral_mm"} or None, with the signs of pose_err()), "first_turn_deg", "final_in_place_turn_deg",
            "planned_final_turn_deg", "drive_reapproaches" (int), "pose_corrections" (the state["corrections"] records),
            "base_drift" ({phase: {"max_pos_mm", "max_yaw_deg", "net_pos_mm", "net_yaw_deg"}}, DRIVE and the CORRECT phases left
            out), "min_base_to_bench_clearance_during_drive_mm" (float or None) and "neck_framing_report" (the framing report or None).
        """
        phases_ = state["phases"]
        dur = {k: (v["end"] - v["start"] - v.get("paused_s", 0.0)) if v["end"] is not None else None for k, v in phases_.items() if k != "DONE"}
        final = None
        if M["handoff_base"] is not None:
            ex, ey = gx - M["handoff_base"][0], gy - M["handoff_base"][1]
            final = {"pos_err_mm": 1000 * math.hypot(ex, ey), "yaw_err_deg": math.degrees(wrap(M["handoff_base"][2] - gyaw)),
                     "along_mm": 1000 * (ex * math.cos(gyaw) + ey * math.sin(gyaw)),          # > 0: short of the staging pose, farther from the bench
                     "lateral_mm": 1000 * (-ex * math.sin(gyaw) + ey * math.cos(gyaw))}       # > 0: the staging pose is to the base's left
        drift = {k: {"max_pos_mm": 1000 * v["max_pos"], "max_yaw_deg": math.degrees(v["max_yaw"]),
                     "net_pos_mm": 1000 * v.get("net_pos", 0.0), "net_yaw_deg": math.degrees(v.get("net_yaw", 0.0))}
                 for k, v in M["drift"].items() if k != "DRIVE" and not k.startswith("CORRECT")}
        arr = state["arrival"]
        return {
            "staging_error": state["error"], "phase_durations_s": dur, "phase_times": {k: [v["start"], v["end"]] for k, v in phases_.items()},
            "arrival_at_end_of_drive": ({"pos_err_mm": 1000 * arr["pos_err"], "yaw_err_deg": arr["yaw_err_deg"], "ok": arr["ok"]} if arr else None),
            "base_pose_error_at_handoff": final, "first_turn_deg": state["first_turn_deg"], "final_in_place_turn_deg": state["final_turn_deg"],
            "planned_final_turn_deg": state["planned_final_turn_deg"], "drive_reapproaches": state["reapproaches"],
            "pose_corrections": state["corrections"], "base_drift": drift,
            "min_base_to_bench_clearance_during_drive_mm": None if M["min_clearance"] is None else 1000 * M["min_clearance"],
            "neck_framing_report": state["framing_report"]}

    # ------------------------------------------------------------------ restoring what the operator moved
    AFTER_PEDESTAL = ("CORRECT_PEDESTAL", "ARMS", "CORRECT_ARMS", "NECK", "DONE")

    def restore_step(obs, t, dt):
        """After a hand-back, puts back what this stage still needs and an operator may have moved, smoothly and one thing at a time.

        pedestal: once the PEDESTAL phase is over it must be at the staging height; it is re-ramped from the applied height at
        pedestal_speed and waited for until settled. neck: in NECK the framing is re-run (the phase does it when neck_sent is cleared);
        after the stage is DONE the framing is re-run here and the neck moves there at the loop's neck speed. Before NECK the neck is not
        needed (NECK frames it anyway). When everything is back it clears P["restore"] and P["neck_resent"].

        Args:
            obs (dict): The observation; uses "applied" ("pedestal"), "pedestal_height", "joint_angles" and "joint_velocities".
            t (float): The simulation time in seconds.
            dt (float): The control tick length in seconds.

        Returns:
            tuple: (commands, finished). `commands` is a list of pedestal or neck commands (see make_staging_source()), possibly empty;
            `finished` is True when nothing is left to restore.
        """
        phase = "DONE" if state["done"] else state["phase"]
        if phase in AFTER_PEDESTAL:
            target = task_cfg["pedestal_q"]
            applied = obs["applied"]["pedestal"]
            if abs(applied - target) > 1e-9:
                step = cfg["pedestal_speed"] * dt
                return [{"mode": "pedestal", "height": applied + max(-step, min(step, target - applied))}], False
            if abs(obs["pedestal_height"] - target) >= cfg["pedestal_tol"] or \
                    not still_for(t, abs(obs["joint_velocities"][ped_vadr]) < cfg["pedestal_settle_vel"], cfg["pedestal_settle_s"]):
                return [], False
        if phase == "NECK":
            P["neck_sent"] = False
        elif phase == "DONE" and neck is not None:
            if not P["neck_resent"]:
                targets, report = frame_points(model, data, points_fn(model, data, task_cfg))
                state["framing_report"] = report
                P["neck_targets"], P["neck_resent"] = targets, True
                return [{"mode": "neck", "neck_targets": targets}], False
            q = np.array([obs["joint_angles"][a] for a in neck["qadr"]])
            goal_q = np.array([P["neck_targets"][n] for n in neck["names"]])
            qd = max(abs(obs["joint_velocities"][v]) for v in neck["vadr"])
            if not (np.abs(q - goal_q).max() < cfg["neck_tol"] and still_for(t, qd < cfg["neck_settle_vel"], cfg["neck_settle_s"])):
                return [], False
        P["restore"], P["neck_resent"] = False, False
        return [], True

    def resume():
        """Prepares the source for the control loop handing control back after an operator had it.

        Every subsystem restarts from where the operator left it: the base (the controllers slew from the applied Twist, always), the
        arm (always rate-limited from the applied targets), the pedestal (its phase ramps from the applied height) and the neck (the
        loop slews it) need nothing here; the gripper is rate-limited from the applied target until it is back on the path. It sets
        P["lim_grip"], sets P["restore"] (unless RESTORE_ON_RESUME is False) and clears P["still_since"].
        """
        P["lim_grip"] = True
        P["restore"] = True if RESTORE_ON_RESUME else False
        P["still_since"] = None

    return {"name": "staging", "step": step, "state": state, "observe": observe, "report": report, "resume": resume, "restore_step": restore_step, "restoring": lambda: P["restore"]}
